import React from "react";

export interface StarRatingProps {
  /** Current rating value, 1..5. */
  value: number;
  /** Called with the new rating when the user selects a star. */
  onChange: (value: number) => void;
  /** Render a static "N out of 5 stars" image instead of interactive inputs. */
  readOnly?: boolean;
  /** Accessible name for the group (or the image in readOnly mode). */
  label?: string;
}

const MAX = 5;

/**
 * Star rating implemented as a native radio group.
 *
 * Native radios give us keyboard support for free: Arrow keys move between
 * options and (unlike Tab) follow the roving-checked-state pattern — focus
 * lands on whichever radio is checked. We only need to make sure the checked
 * radio stays focused after programmatic or pointer-driven changes, and
 * visually replace the radios with stars.
 */
export function StarRating({
  value,
  onChange,
  readOnly = false,
  label = "Rating",
}: StarRatingProps): React.ReactElement {
  const name = React.useId();

  if (readOnly || value < 1 || value > MAX) {
    return (
      <img
        role="img"
        aria-label={`${value} out of ${MAX} stars`}
        src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg'/%3E"
        alt=""
      />
    );
  }

  return (
    <div role="radiogroup" aria-label={label}>
      {Array.from({ length: MAX }, (_, i) => i + 1).map((starValue) => (
        <label key={starValue} style={{ cursor: "pointer" }}>
          <input
            type="radio"
            name={name}
            value={starValue}
            checked={value === starValue}
            onChange={() => onChange(starValue)}
          />
          <span aria-hidden="true">
            {starValue <= value ? "\u2605" : "\u2606"}
          </span>
        </label>
      ))}
    </div>
  );
}

export default StarRating;

