import React from "react";
import { cleanup, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, describe, expect, it, vi } from "vitest";
import { StarRating } from "./StarRating";

afterEach(cleanup);

describe("StarRating", () => {
  it("renders five radio inputs inside a radiogroup", () => {
    render(<StarRating value={3} onChange={() => {}} />);
    expect(screen.getByRole("radiogroup")).toBeInTheDocument();
    expect(screen.getAllByRole("radio")).toHaveLength(5);
  });

  it("checks the radio matching value", () => {
    render(<StarRating value={3} onChange={() => {}} />);
    const radios = screen.getAllByRole("radio");
    expect(radios[2]).toBeChecked();
    expect(radios[0]).not.toBeChecked();
  });

  it("ArrowDown moves to the next option and fires onChange with its number", async () => {
    const onChange = vi.fn();
    const user = userEvent.setup();
    render(<StarRating value={3} onChange={onChange} />);

    // Roving checked state: focus starts on the checked radio.
    const radios = screen.getAllByRole("radio");
    await user.tab();
    expect(radios[2]).toHaveFocus();

    await user.keyboard("{ArrowDown}");
    expect(onChange).toHaveBeenCalledWith(4);
    expect(screen.getAllByRole("radio")[3]).toBeChecked();
    expect(screen.getAllByRole("radio")[3]).toHaveFocus();
  });

  it("ArrowUp moves to the previous option and fires onChange with its number", async () => {
    const onChange = vi.fn();
    const user = userEvent.setup();
    render(<StarRating value={3} onChange={onChange} />);

    await user.tab();
    await user.keyboard("{ArrowUp}");
    expect(onChange).toHaveBeenCalledWith(2);
    expect(screen.getAllByRole("radio")[1]).toBeChecked();
    expect(screen.getAllByRole("radio")[1]).toHaveFocus();
  });

  it("clicking the fourth star yields 4", async () => {
    const onChange = vi.fn();
    const user = userEvent.setup();
    render(<StarRating value={0} onChange={onChange} />);

    await user.click(screen.getAllByRole("radio")[3]);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(4);
  });

  it("readOnly renders an img role element with an aria-label instead of inputs", () => {
    render(<StarRating value={3} onChange={() => {}} readOnly />);
    expect(screen.queryAllByRole("radio")).toHaveLength(0);
    const image = screen.getByRole("img");
    expect(image).toHaveAccessibleName("3 out of 5 stars");
  });
});

